fn add(releases: &mut StableReleases, version: Stable, release_date: Date, hosts: &[&str]) {
    let toolchains = hosts
        .iter()
        .map(|host| {
            Toolchain::new(
                Channel::Stable(version.clone()),
                Some(release_date.clone()),
                Target::from_target_triple_or_unknown(host),
                HashSet::new(),
                HashSet::new(),
            )
        })
        .collect::<Vec<_>>();

    releases.add(RustRelease::new(version, Some(release_date), toolchains));
}
